import json, torch
from transformers import AutoModelForCausalLM, AutoTokenizer
from peft import PeftModel
from huggingface_hub import login

login(token="PASTE_YOUR_NEW_ROTATED_TOKEN_HERE")  # <-- after you rotate it

BASE = "Qwen/Qwen2.5-3B-Instruct"
REPO = "vijay5799760/Qwen2.5-3B-SEntFiN-LoRA-HPtuned"

tok = AutoTokenizer.from_pretrained(REPO)
if tok.pad_token is None:
    tok.pad_token = tok.eos_token
base = AutoModelForCausalLM.from_pretrained(BASE, dtype=torch.bfloat16, device_map="cuda")
model = PeftModel.from_pretrained(base, REPO)
model.eval()
print("Model loaded")

PROMPT = ("Classify the sentiment of the following financial headline as exactly one word: "
          "positive, negative, or neutral.\n\nHeadline: {headline}\nSentiment:")

def get_label_token_ids():
    variants = {"positive": ["positive", " positive", "Positive", " Positive"],
                "negative": ["negative", " negative", "Negative", " Negative"],
                "neutral": ["neutral", " neutral", "Neutral", " Neutral"]}
    out = {}
    for label, vs in variants.items():
        ids = set()
        for v in vs:
            t = tok.encode(v, add_special_tokens=False)
            if t: ids.add(t[0])
        out[label] = list(ids)
    return out

label_token_ids = get_label_token_ids()

@torch.no_grad()
def score(text):
    prompt = PROMPT.format(headline=text)
    enc = tok(prompt, return_tensors="pt", truncation=True, max_length=96).to(model.device)
    logits = model(**enc).logits[0, -1]
    scores = {l: torch.logsumexp(logits[ids], dim=0) for l, ids in label_token_ids.items()}
    probs = torch.softmax(torch.stack([scores["positive"], scores["negative"], scores["neutral"]]), dim=0)
    return float(probs[0] - probs[1])

